// ============ Validation ============
public static void validateConfig(Mcp.Config msg) throws ProtoException {
if (msg == null) {
return;
}
// Validate anthropicApiKey (assert_required)
if (msg.getAnthropicApiKey().isEmpty()) {
throw new ProtoException(ProtoException.INVALID_ARGUMENT,"field anthropicApiKey is required");
}
// Validate maxRetries (assert_ge: 1)
if (msg.getMaxRetries() < 1) {
throw new ProtoException(ProtoException.INVALID_ARGUMENT,String.format("field maxRetries must be >= 1, got: %s", msg.getMaxRetries()));
}
// Validate maxRetries (assert_le: 10)
if (msg.getMaxRetries() > 10) {
throw new ProtoException(ProtoException.INVALID_ARGUMENT,String.format("field maxRetries must be <= 10, got: %s", msg.getMaxRetries()));
}
// Validate sessionTtlSeconds (assert_duration: POSITIVE)
if (msg.getSessionTtlSeconds() <= 0) {
throw new ProtoException(ProtoException.INVALID_ARGUMENT,String.format("field sessionTtlSeconds must be positive (> 0), got: %d", msg.getSessionTtlSeconds()));
}
}
public static void validateToolAuthorization(Mcp.ToolAuthorization msg) throws ProtoException {
if (msg == null) {
return;
}
// Validate service (assert_required)
if (msg.getService().isEmpty()) {
throw new ProtoException(ProtoException.INVALID_ARGUMENT,"field service is required");
}
}
