// ============ Merge ============
public static Mcp.Config.Builder mergeConfig(Mcp.Config dst, Mcp.Config src) {
Mcp.Config.Builder builder = dst.toBuilder();
if (dst.getAnthropicApiKey().isEmpty()) { builder.setAnthropicApiKey(src.getAnthropicApiKey()); }
if (dst.getModel().isEmpty()) { builder.setModel(src.getModel()); }
if (dst.getMaxRetries() == 0) { builder.setMaxRetries(src.getMaxRetries()); }
if (dst.getSessionTtlSeconds() == 0) { builder.setSessionTtlSeconds(src.getSessionTtlSeconds()); }
return builder;
}
public static Mcp.ToolAuthorization.Builder mergeToolAuthorization(Mcp.ToolAuthorization dst, Mcp.ToolAuthorization src) {
Mcp.ToolAuthorization.Builder builder = dst.toBuilder();
if (dst.getService().isEmpty()) { builder.setService(src.getService()); }
if (dst.getMethodsList().isEmpty()) { builder.addAllMethods(src.getMethodsList()); }
return builder;
}
public static Mcp.AgentToken.Builder mergeAgentToken(Mcp.AgentToken dst, Mcp.AgentToken src) {
Mcp.AgentToken.Builder builder = dst.toBuilder();
if (dst.getService().isEmpty()) { builder.setService(src.getService()); }
if (dst.getToken().isEmpty()) { builder.setToken(src.getToken()); }
return builder;
}
public static Mcp.AssistToolRequest.Builder mergeAssistToolRequest(Mcp.AssistToolRequest dst, Mcp.AssistToolRequest src) {
Mcp.AssistToolRequest.Builder builder = dst.toBuilder();
if (dst.getRequestedToolsList().isEmpty()) { builder.addAllRequestedTools(src.getRequestedToolsList()); }
if (dst.getJustification().isEmpty()) { builder.setJustification(src.getJustification()); }
return builder;
}
public static Mcp.AssistRequest.Builder mergeAssistRequest(Mcp.AssistRequest dst, Mcp.AssistRequest src) {
Mcp.AssistRequest.Builder builder = dst.toBuilder();
if (dst.getSessionId().isEmpty()) { builder.setSessionId(src.getSessionId()); }
if (dst.getTargetType().isEmpty()) { builder.setTargetType(src.getTargetType()); }
if (dst.getPrompt().isEmpty()) { builder.setPrompt(src.getPrompt()); }
if (dst.getAuthorizedToolsList().isEmpty()) { builder.addAllAuthorizedTools(src.getAuthorizedToolsList()); }
if (dst.getAgentTokensList().isEmpty()) { builder.addAllAgentTokens(src.getAgentTokensList()); }
return builder;
}
public static Mcp.AssistResponse.Builder mergeAssistResponse(Mcp.AssistResponse dst, Mcp.AssistResponse src) {
Mcp.AssistResponse.Builder builder = dst.toBuilder();
if (dst.getSessionId().isEmpty()) { builder.setSessionId(src.getSessionId()); }
if (dst.getResponseTypeValue() == 0) { builder.setResponseTypeValue(src.getResponseTypeValue()); }
if (!dst.hasToolRequest() && src.hasToolRequest()) { builder.setToolRequest(src.getToolRequest()); }
else if (dst.hasToolRequest() && src.hasToolRequest()) { builder.setToolRequest(mergeAssistToolRequest(dst.getToolRequest(), src.getToolRequest()).build()); }
if (dst.getResultType().isEmpty()) { builder.setResultType(src.getResultType()); }
if (dst.getResultJson().isEmpty()) { builder.setResultJson(src.getResultJson()); }
return builder;
}
public static Mcp.McpConfigState.Builder mergeMcpConfigState(Mcp.McpConfigState dst, Mcp.McpConfigState src) {
Mcp.McpConfigState.Builder builder = dst.toBuilder();
if (!dst.hasConfig() && src.hasConfig()) { builder.setConfig(src.getConfig()); }
else if (dst.hasConfig() && src.hasConfig()) { builder.setConfig(mergeConfig(dst.getConfig(), src.getConfig()).build()); }
return builder;
}
