public static Map<String, String> configToEnvVar(Mcp.Config msg) {
Map<String, String> result = new HashMap<>();
result.put("PROTO_CONFIG_ANTHROPIC_API_KEY", msg.getAnthropicApiKey());
result.put("PROTO_CONFIG_MODEL", msg.getModel());
result.put("PROTO_CONFIG_MAX_RETRIES", String.valueOf(msg.getMaxRetries()));
result.put("PROTO_CONFIG_SESSION_TTL_SECONDS", String.valueOf(msg.getSessionTtlSeconds()));
return result;
}
public static Mcp.Config.Builder configFromEnvVar(Map<String, String> env) {
Mcp.Config.Builder builder = Mcp.Config.newBuilder();
String val;
val = env.get("PROTO_CONFIG_ANTHROPIC_API_KEY");
if (val != null && !val.isEmpty()) {
builder.setAnthropicApiKey(val);
}
val = env.get("PROTO_CONFIG_MODEL");
if (val != null && !val.isEmpty()) {
builder.setModel(val);
}
val = env.get("PROTO_CONFIG_MAX_RETRIES");
if (val != null && !val.isEmpty()) {
builder.setMaxRetries(Integer.parseInt(val));
}
val = env.get("PROTO_CONFIG_SESSION_TTL_SECONDS");
if (val != null && !val.isEmpty()) {
builder.setSessionTtlSeconds(Long.parseLong(val));
}
return builder;
}
